    async function send(message, silent = false) { const text = safeText(message).trim(); if (!text) return; if (controller) controller.abort(); controller = new AbortController(); audio.pause(); speaking = false; input.value = ''; setState('thinking'); setLoading(text); try { const response = await apiFetch('/api/chat', { method: 'POST', headers: { 'Content-Type': 'application/json' }, signal: controller.signal, body: JSON.stringify({ session_id: sessionId, timestamp: new Date().toISOString(), payload: { type: 'text', content: text } }) }); if (response.status === 401) { addAnswer('Not authorized — no API token was provided.', 'authorization', true, text); setState('error'); return; } if (!response.ok) { addAnswer('The server returned an error (status ' + response.status + ').', 'server error', true, text); setState('error'); return; } const data = await response.json(), action = safeText(data.action_taken); if (action.startsWith('hitl_pending')) addApproval(data.jarvis_response, action, text); else addAnswer(data.jarvis_response, action, false, text, data.research_payload || null, true, data.device_action || null); if (data.audio_base64) { audio.src = 'data:audio/mp3;base64,' + data.audio_base64; audio.onended = () => { speaking = false; setState('idle'); tryAutoListen(); }; speaking = true; setState('speaking'); audio.play().catch(() => { speaking = false; setState('idle'); }); } else { setState('idle'); tryAutoListen(); } } catch (error) { if (error.name !== 'AbortError') { addAnswer('Connection error. Please check that the Jarvis server is available.', 'connection error', true, text); setState('error'); } else clearLoading(); } }
    document.getElementById('researchForm').addEventListener('submit', event => { event.preventDefault(); send(input.value); }); document.querySelectorAll('[data-query]').forEach(button => button.addEventListener('click', () => send(button.dataset.query))); document.querySelectorAll('[data-mode]').forEach(button => button.addEventListener('click', () => { document.querySelectorAll('[data-mode]').forEach(item => item.removeAttribute('aria-current')); button.setAttribute('aria-current', 'page'); openWorkflow(button.dataset.mode); })); document.querySelectorAll('[data-scroll-target]').forEach(button => button.addEventListener('click', () => document.getElementById(button.dataset.scrollTarget)?.scrollIntoView({ behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start' }))); document.getElementById('watchlistForm').addEventListener('submit', event => { event.preventDefault(); const field = document.getElementById('watchlistInput'); addToWatchlist(field.value); field.value = ''; }); document.getElementById('workflowClose').addEventListener('click', () => { workflowPanel.hidden = true; }); workflowForm.addEventListener('submit', event => { event.preventDefault(); const mode = document.getElementById('workflowMode').value, asset = workflowAsset.value.trim().toUpperCase(), benchmark = workflowBenchmark.value.trim().toUpperCase(), timeframe = document.getElementById('workflowTimeframe').value, analysis = document.getElementById('workflowAnalysis').value; const payload = { mode, asset, timeframe, analysis }; if (['compare','relationship'].includes(mode)) payload.benchmark = benchmark; const query = mode === 'asset' ? 'Analyse ' + asset : mode === 'compare' ? 'Compare ' + asset + ' and ' + benchmark : mode === 'history' ? 'Historical research for ' + asset : analysis + ' of ' + asset + ' and ' + benchmark; workflowPanel.hidden = true; runResearchWorkflow(payload, query); }); document.getElementById('clearBtn').addEventListener('click', () => { if (controller) controller.abort(); cancelAllDevicePolling(); audio.pause(); sessionId = newSession(); feed.innerHTML = '<article class="empty-result" id="emptyResearch"><h3>New research session.</h3><p>Your next report will appear here.</p></article>'; updateResearchAlerts([]); setState('idle'); input.focus(); });
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition; if (!SpeechRecognition) { document.getElementById('micBtn').disabled = true; document.getElementById('micBtn').title = 'Speech recognition is unavailable in this browser'; handsFreeBtn.hidden = true; } else { recognition = new SpeechRecognition(); recognition.lang = 'de-DE'; recognition.interimResults = false; document.getElementById('micBtn').addEventListener('click', () => { if (speaking || shell.classList.contains('thinking')) { audio.pause(); speaking = false; if (controller) controller.abort(); } try { recognition.start(); setState('listening'); } catch {} }); recognition.onresult = event => send(event.results[0][0].transcript); recognition.onend = () => { if (!shell.classList.contains('thinking') && !speaking) setState('idle'); }; recognition.onerror = event => { setState('idle'); if (handsFree && ['no-speech','aborted'].includes(event.error)) return; showToast('Voice input was not available. You can still use the text prompt.'); }; }
    renderWatchlist(); renderSavedResearch(); loadProviderStatus(); loadMacroContext(); loadDeviceStatus();
    if ('serviceWorker' in navigator) window.addEventListener('load', () => navigator.serviceWorker.register('/sw.js').catch(() => {}));
